"""Deterministic simulation core for the desync detector.

Units live on an integer grid and execute recorded move commands. Every
tick advances the state in a fully deterministic way, so identical command
streams always produce identical per-tick checksums -- unless somebody
tampered with the recording.
"""

from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass

# Normalized (dx, dy) sign pair -> facing label. Deterministic mapping.
DIRECTIONS = {
    (1, 0): "E",
    (-1, 0): "W",
    (0, 1): "S",
    (0, -1): "N",
    (1, 1): "SE",
    (1, -1): "NE",
    (-1, 1): "SW",
    (-1, -1): "NW",
}


class CommandError(KeyError):
    """Raised when a command references an unknown unit."""


@dataclass
class Unit:
    id: str
    x: int
    y: int
    facing: str = "E"

    def to_dict(self) -> dict:
        return {"id": self.id, "x": self.x, "y": self.y, "facing": self.facing}


def _sign(v: int) -> int:
    return (v > 0) - (v < 0)


class Simulation:
    """A deterministic integer-grid world state."""

    def __init__(self, units):
        # dict keyed by id; iteration order is normalized via sorted ids in
        # canonical_state, so insertion order never affects checksums.
        self.units: dict[str, Unit] = {u.id: u for u in units}

    @classmethod
    def from_specs(cls, specs) -> "Simulation":
        return cls([Unit(**spec) for spec in specs])

    # -- state manipulation -------------------------------------------------

    def clone(self) -> "Simulation":
        return Simulation(
            [Unit(u.id, u.x, u.y, u.facing) for u in self.units.values()]
        )

    def apply(self, cmd: dict) -> None:
        """Apply one recorded move command: {"unit": id, "dx": int, "dy": int}."""
        uid = cmd["unit"]
        if uid not in self.units:
            raise CommandError(uid)
        unit = self.units[uid]
        dx = int(cmd["dx"])
        dy = int(cmd["dy"])
        unit.x += dx
        unit.y += dy
        if dx != 0 or dy != 0:
            unit.facing = DIRECTIONS[(_sign(dx), _sign(dy))]

    def apply_all(self, cmds) -> None:
        for cmd in cmds:
            self.apply(cmd)

    # -- serialization / checksum -------------------------------------------

    def canonical_state(self) -> str:
        payload = {
            "units": [self.units[uid].to_dict() for uid in sorted(self.units)]
        }
        return json.dumps(payload, sort_keys=True, separators=(",", ":"))

    def checksum(self) -> str:
        return hashlib.sha256(self.canonical_state().encode("utf-8")).hexdigest()[:16]

    def snapshot(self) -> dict:
        return {uid: self.units[uid].to_dict() for uid in sorted(self.units)}


# ---------------------------------------------------------------------------
# Recording construction (used by tools/tests to produce reference replays)
# ---------------------------------------------------------------------------

RECORDING_VERSION = 1


def build_recording(unit_specs, commands_per_tick) -> dict:
    """Simulate the given command stream and record per-tick checksums."""
    sim = Simulation.from_specs(unit_specs)
    ticks = []
    for cmds in commands_per_tick:
        sim.apply_all(cmds)
        ticks.append({"commands": list(cmds), "checksum": sim.checksum()})
    return {
        "version": RECORDING_VERSION,
        "initial_state": {"units": [dict(s) for s in unit_specs]},
        "ticks": ticks,
    }

